import json, re, random, chess, sys

rules = json.load(open('/app/re.json'))

def run_solution(fen):
    for pattern, repl in rules:
        fen = re.sub(pattern, repl, fen)
    return fen.split("\n")

def norm(s):
    return " ".join(s.split(" ")[:-2])

def compare(fen):
    our = run_solution(fen)
    board = chess.Board(fen)
    expected = set()
    for move in board.legal_moves:
        if move.promotion and move.promotion != chess.QUEEN:
            continue
        b = board.copy()
        b.push(move)
        expected.add(norm(b.fen()))
    ours = [norm(x) for x in our]
    # replicate checker acceptance
    bad = [x for x in ours if x not in expected and x.rpartition(" ")[0] + " -" not in expected]
    if bad or len(ours) != len(expected):
        print("MISMATCH", fen)
        print("ours", len(ours), "expected", len(expected))
        for x in bad:
            print("  bad:", x)
        extra = set(ours) - expected
        missing = expected - set(ours)
        for x in list(extra)[:10]: print("  extra:", x)
        for x in list(missing)[:10]: print("  missing:", x)
        return False
    return True

def test_game(seed):
    rng = random.Random(seed)
    board = chess.Board()
    n = 0
    while not board.is_game_over() and n < 200:
        if board.turn == chess.WHITE:
            n += 1
            if not compare(board.fen()):
                return False
        moves = list(board.legal_moves)
        # bias toward castling/promotions occasionally
        board.push(rng.choice(moves))
    return True

if __name__ == '__main__':
    start = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 10
    for seed in range(start, start + count):
        print("seed", seed, flush=True)
        if not test_game(seed):
            print("FAIL seed", seed)
            sys.exit(1)
    print("ALL OK")

